<?php require "wp-load.php"; global $wpdb; echo "Transients: " . $wpdb->get_var("SELECT COUNT(*) FROM {$wpdb->options} WHERE option_name LIKE '_transient_%'") . "\n"; echo "Autoload MB: " . round($wpdb->get_var("SELECT SUM(LENGTH(option_value)) FROM {$wpdb->options} WHERE autoload = 'yes' OR autoload = 'on'") / 1024 / 1024, 2) . "\n"; echo "Postmeta: " . $wpdb->get_var("SELECT COUNT(*) FROM {$wpdb->postmeta}") . "\n";
